package com.couchbase.client.scala.query.conversational

import com.couchbase.client.core.msg.query.QueryChunkRow
import com.couchbase.client.scala.codec.JsonDeserializer
import com.couchbase.client.scala.query.QueryMetaData
import com.couchbase.client.scala.util.RowTraversalUtil

import scala.util.Try

/** The results of a conversational query, or of a `Chat.ask`.
  *
  * @param rows               any rows returned from executing the generated statement
  * @param metaData           any additional information related to the request
  * @param generatedStatement the statement generated by the query service, if one was returned
  *
  * @define SupportedTypes The rows can be converted into the user's desired type.  This can be any type for which an
  *                        implicit `JsonDeserializer[T]` can be found, and can include `JsonObject`, a case class, String,
  *                        or one of a number of supported third-party JSON libraries; see
  *                        [[https://docs.couchbase.com/scala-sdk/current/howtos/json.html these JSON docs]] for a full list
  */
case class ConversationalQueryResult(
    private[scala] val rows: Seq[QueryChunkRow],
    metaData: ConversationalQueryMetaData,
    generatedStatement: Option[String]
) {

  /** Returns a collection of any returned rows.  All rows are buffered from the query service first.
    *
    * $SupportedTypes
    */
  def rowsAs[T](implicit deserializer: JsonDeserializer[T]): Try[collection.Seq[T]] = {
    RowTraversalUtil.traverse(rows.iterator.map(row => {
      deserializer.deserialize(row.data())
    }))
  }
}
